#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# ──────────────────────────────────────────────────────────────────────────
# STAGES: habilitar Gmail (gmail.send + gmail.readonly) en la cuenta técnica
# del Agente 1. Ticket #41, decisión D11 de la spec #38.
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=6

# Firefox abre la pestaña en su ventana existente, que puede estar en otro
# workspace de Hyprland: además de abrirla, el link queda visible para copiar.
open_url() {
  local url="$1"
  { xdg-open "$url" || true; } >/dev/null 2>&1
  printf '  %s↗ abrí en Firefox (puede estar en otro workspace):%s\n' "$GREEN" "$RESET"
  printf '    %s%s%s\n' "$BOLD" "$url" "$RESET"
}
ENV_FILE="$HOME/.config/agente1/workspace-d2.env"
AGENTE1_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
SCOPES="https://www.googleapis.com/auth/drive https://www.googleapis.com/auth/documents https://www.googleapis.com/auth/spreadsheets https://www.googleapis.com/auth/gmail.send https://www.googleapis.com/auth/gmail.readonly"

if [[ ! -f "$ENV_FILE" ]]; then
  printf '%sNo existe %s: este wizard actualiza una cuenta ya configurada.%s\n' "$RED" "$ENV_FILE" "$RESET"
  exit 1
fi

banner "Gmail para la cuenta técnica del Agente 1"

stage "Proyecto de Google Cloud"
say "Necesito el Project ID del proyecto donde vive el cliente OAuth del Agente 1."
say "Solo se usa para armar los links; no se guarda."
note "Consola de Google Cloud (etapas 1-3 y 6): la cuenta que ADMINISTRA el proyecto,"
note "es decir, la que lo creó el 28/09. Puede ser la tuya o la del bot."
note "Si no sabés cuál: en console.cloud.google.com, con cada cuenta, mirá cuál ve el"
note "proyecto en el selector de arriba. El Project ID está en esa misma lista."
note "Playground (etapa 4): SIEMPRE la cuenta del bot."
open_url "https://console.cloud.google.com/projectselector2/home/dashboard"
ask GCP_PROJECT_ID "Project ID:"
[[ -n "$GCP_PROJECT_ID" ]] || { warn "Sin Project ID no puedo seguir."; exit 1; }
open_url "https://console.cloud.google.com/apis/library/gmail.googleapis.com?project=${GCP_PROJECT_ID}"
step "En la página de Gmail API, hacé clic en «Habilitar» (Enable)."
step "Si ya dice «Administrar» (Manage), ya está habilitada: seguí."
pause "¿Gmail API habilitada? Enter para seguir"

stage "Permisos en la pantalla de autorización"
open_url "https://console.cloud.google.com/auth/scopes?project=${GCP_PROJECT_ID}"
step "Google Auth Platform → Data Access → «Add or remove scopes»."
step "En «Manually add scopes», pegá estas dos líneas y hacé clic en «Add to table»:"
note "    https://www.googleapis.com/auth/gmail.send"
note "    https://www.googleapis.com/auth/gmail.readonly"
step "Marcalas en la tabla, «Update» y después «Save»."
note "La app es Internal: Google no exige verificación para estos permisos."
pause "¿Guardado? Enter para seguir"

stage "Redirect URI del Playground"
open_url "https://console.cloud.google.com/auth/clients?project=${GCP_PROJECT_ID}"
CLIENT_ID_ACTUAL=$(_existing AGENTE1_WORKSPACE_OAUTH_CLIENT_ID || true)
step "Abrí el cliente OAuth cuyo Client ID termina en: ...${CLIENT_ID_ACTUAL: -24}"
step "En «Authorized redirect URIs», verificá que esté:"
note "    https://developers.google.com/oauthplayground"
step "Si no está, agregala y guardá (puede tardar unos minutos en aplicarse)."
pause "¿Redirect URI presente? Enter para seguir"

stage "Nuevo refresh token con OAuth Playground"
open_url "https://developers.google.com/oauthplayground"
step "Arriba a la derecha, el engranaje (OAuth 2.0 configuration):"
step "  marcá «Use your own OAuth credentials» y pegá Client ID y Client secret."
if command -v wl-copy >/dev/null 2>&1; then
  if confirm "¿Copio el Client ID al portapapeles?"; then
    printf '%s' "$CLIENT_ID_ACTUAL" | wl-copy; say "Client ID copiado."
  fi
  if confirm "¿Copio el Client secret al portapapeles? (no se muestra en pantalla)"; then
    _existing AGENTE1_WORKSPACE_OAUTH_CLIENT_SECRET | wl-copy; say "Client secret copiado."
  fi
else
  note "Los dos valores están en $ENV_FILE (AGENTE1_WORKSPACE_OAUTH_CLIENT_ID / _SECRET)."
fi
step "Cerrá la configuración. En «Step 1», en «Input your own scopes», pegá:"
note "    $SCOPES"
if command -v wl-copy >/dev/null 2>&1 && confirm "¿Copio la lista de scopes al portapapeles?"; then
  printf '%s' "$SCOPES" | wl-copy; say "Scopes copiados."
fi
step "«Authorize APIs» → iniciá sesión con la CUENTA DEL BOT (no la tuya) → Permitir."
step "En «Step 2», «Exchange authorization code for tokens»."
step "Copiá el valor de «Refresh token»."
warn "El refresh token es un secreto: no lo pegues en ningún otro lado."
ask_secret NUEVO_REFRESH_TOKEN "Pegá el refresh token (no se ve):"
[[ -n "$NUEVO_REFRESH_TOKEN" ]] || { warn "No recibí ningún token."; exit 1; }
if [[ "$NUEVO_REFRESH_TOKEN" == "$(_existing AGENTE1_WORKSPACE_OAUTH_REFRESH_TOKEN || true)" ]]; then
  warn "Es el mismo token que ya estaba: no hubo cambio."
elif confirm "¿Reemplazo el refresh token actual? (queda backup en ${ENV_FILE}.bak, modo 600)"; then
  install -m 600 "$ENV_FILE" "${ENV_FILE}.bak"
  write_env AGENTE1_WORKSPACE_OAUTH_REFRESH_TOKEN "$NUEVO_REFRESH_TOKEN"
  chmod 600 "$ENV_FILE"
else
  SKIPPED+=("Reemplazar AGENTE1_WORKSPACE_OAUTH_REFRESH_TOKEN (cancelado)")
fi
unset NUEVO_REFRESH_TOKEN

stage "Verificación de permisos"
say "Genero un access token con el refresh token guardado y pregunto a Google qué permisos tiene."
note "No se imprime ningún secreto: solo la lista de scopes."
if VERIFICACION=$(cd "$AGENTE1_DIR" && set -a && . "$ENV_FILE" && set +a && .venv/bin/python - <<'PY'
import json, urllib.parse, urllib.request
from agente1.workspace_auth import construir_token_provider
token = construir_token_provider().obtener_access_token()
url = "https://oauth2.googleapis.com/tokeninfo?" + urllib.parse.urlencode({"access_token": token})
print(json.load(urllib.request.urlopen(url, timeout=10)).get("scope", ""))
PY
); then
  say "Scopes concedidos:"
  for s in $VERIFICACION; do note "    $s"; done
  FALTAN=()
  for s in $SCOPES; do [[ " $VERIFICACION " == *" $s "* ]] || FALTAN+=("$s"); done
  if (( ${#FALTAN[@]} )); then
    warn "Faltan: ${FALTAN[*]}"
    warn "Si la consola de administración de Workspace bloquea Gmail, registralo en #41 (needs-info)."
    SKIPPED+=("Scopes faltantes: ${FALTAN[*]}")
  else
    say "${GREEN}✓ Están los cinco permisos.${RESET}"
  fi
else
  warn "La verificación falló (token inválido o sin red). El backup está en ${ENV_FILE}.bak."
  SKIPPED+=("Verificación de scopes")
fi
pause

stage "Limpieza del redirect URI"
say "Buena práctica: quitar el Playground de los redirect URIs cuando ya no se usa."
note "Si lo quitás, para volver a correr este wizard hay que agregarlo de nuevo."
if confirm "¿Querés quitarlo ahora?"; then
  open_url "https://console.cloud.google.com/auth/clients?project=${GCP_PROJECT_ID}"
  step "Abrí el cliente OAuth, borrá https://developers.google.com/oauthplayground y guardá."
  pause "¿Listo? Enter para terminar"
else
  SKIPPED+=("Quitar el redirect URI del Playground (opcional)")
fi

finish
note "Siguiente: avisar a DSI los permisos efectivos (ticket #41) y borrar ${ENV_FILE}.bak cuando todo funcione."
